package com.github.jasparigus.lefthanded;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(LeftHandedConfig.GROUP)
public interface LeftHandedConfig extends Config
{
	String GROUP = "left-handed";

	public enum LeftHandMode
	{
		OFF,
		ALWAYS,
		BOW_ONLY
	}

	@ConfigItem(
		keyName = "mode",
		name = "Mode",
		description = "OFF: nothing. ALWAYS: mirror your character always. BOW_ONLY: mirror while a bow is wielded",
		position = 0
	)
	default LeftHandMode mode()
	{
		return LeftHandMode.OFF;
	}

	@ConfigItem(
		keyName = "mirrorCrossbows",
		name = "Mirror crossbows",
		description = "In BOW ONLY mode, crossbows also trigger the mirror. OSRS crossbows are one-handed, " +
			"so unchecking this (no mirror for crossbows) is reasonable if you prefer to think of them as " +
			"trigger-hand weapons.",
		position = 1
	)
	default boolean mirrorCrossbows()
	{
		return true;
	}
}

package com.github.jasparigus.lefthanded;

import net.runelite.api.GameObject;
import net.runelite.api.Model;
import net.runelite.api.Projection;
import net.runelite.api.Renderable;
import net.runelite.api.Scene;
import net.runelite.api.SceneTileModel;
import net.runelite.api.SceneTilePaint;
import net.runelite.api.Texture;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.api.hooks.DrawCallbacks;

import java.util.Set;
import java.util.function.BooleanSupplier;
import java.util.function.Predicate;

/**
 * Wraps the renderer occupying the client's draw callbacks slot (the GPU plugin) and mirrors the
 * local player's mesh for the duration of its {@code drawTemp} call - the point where the game
 * client hands the actor's live model to the renderer, which reads it synchronously while
 * uploading (verified: edits made at BeforeRender or the renderable draw callback never reach the
 * upload, and unrelated models sharing the same arrays would be corrupted by persistent edits).
 * Vertices and face winding are negated around the delegate call; both operations are
 * self-inverse, so the model is exactly restored afterwards, leaving no plugin-owned state and
 * never persistently touching arrays shared with other actors' models.
 */
final class LeftHandedDrawCallbacks implements DrawCallbacks
{
	private final DrawCallbacks delegate;
	private final BooleanSupplier mirrorActive;
	private final Predicate<GameObject> isLocalPlayerEntity;


	LeftHandedDrawCallbacks(DrawCallbacks delegate, BooleanSupplier mirrorActive, Predicate<GameObject> isLocalPlayerEntity)
	{
		this.delegate = delegate;
		this.mirrorActive = mirrorActive;
		this.isLocalPlayerEntity = isLocalPlayerEntity;
	}

	DrawCallbacks getDelegate()
	{
		return delegate;
	}

	/** Hard kill-switch: cleared on plugin shutdown. Must not depend on config after shutdown -
	 * the Config proxy keeps returning the last saved values (e.g. ALWAYS) even once the plugin
	 * is disabled, so a wrapper left in the slot by a renderer that reclaimed it would otherwise
	 * mirror forever. */
	private volatile boolean enabled = true;

	public void setEnabled(boolean enabled)
	{
		this.enabled = enabled;
	}

	@Override
	public void drawTemp(Projection worldProjection, Scene scene, GameObject gameObject,
		Model model, int orientation, int x, int y, int z)
	{
		// The model reaching drawTemp is a shared scratch instance (identical for all entities),
		// so the only per-entity discriminator here is the scene entity itself.
		final boolean mirror = enabled && model != null && model.getVerticesCount() > 0
			&& mirrorActive.getAsBoolean() && isLocalPlayerEntity.test(gameObject);
		if (!mirror)
		{
			delegate.drawTemp(worldProjection, scene, gameObject, model, orientation, x, y, z);
			return;
		}
		// Only this one draw is mirrored; restoring in finally guarantees shared arrays
		// (face indices alias other actors' models) are never left edited.
		MeshMirror.mirrorModelX(model);
		try
		{
			delegate.drawTemp(worldProjection, scene, gameObject, model, orientation, x, y, z);
		}
		finally
		{
			MeshMirror.mirrorModelX(model);
		}
	}

	@Override
	public void drawDynamic(Projection worldProjection, Scene scene, TileObject tileObject,
		Renderable renderable, Model model, int orientation, int x, int y, int z)
	{
		delegate.drawDynamic(worldProjection, scene, tileObject, renderable, model, orientation, x, y, z);
	}

	@Override
	public void drawDynamic(int renderThreadId, Projection worldProjection, Scene scene, TileObject tileObject,
		Renderable renderable, Model model, int orientation, int x, int y, int z)
	{
		delegate.drawDynamic(renderThreadId, worldProjection, scene, tileObject, renderable, model, orientation, x, y, z);
	}

	// --- everything else: pure delegation ---
	// NOT optional: the DrawCallbacks interface defaults are empty/no-op, so any method not
	// forwarded here would silently drop that part of the render (objects, zones, scene passes).

	@Override
	public void draw(Projection projection, Scene scene, Renderable renderable, int orientation, int x, int y, int z, long hash)
	{
		delegate.draw(projection, scene, renderable, orientation, x, y, z, hash);
	}

	@Override
	public void drawScenePaint(Scene scene, SceneTilePaint paint, int plane, int tileX, int tileZ)
	{
		delegate.drawScenePaint(scene, paint, plane, tileX, tileZ);
	}

	@Override
	public void drawSceneTileModel(Scene scene, SceneTileModel model, int tileX, int tileZ)
	{
		delegate.drawSceneTileModel(scene, model, tileX, tileZ);
	}

	@Override
	public void draw(int overlayColor)
	{
		delegate.draw(overlayColor);
	}

	@Override
	public void drawScene(double cameraX, double cameraY, double cameraZ, double cameraPitch, double cameraYaw, int plane)
	{
		delegate.drawScene(cameraX, cameraY, cameraZ, cameraPitch, cameraYaw, plane);
	}

	@Override
	public void postDrawScene()
	{
		delegate.postDrawScene();
	}

	@Override
	public void animate(Texture texture, int diff)
	{
		delegate.animate(texture, diff);
	}

	@Override
	public void loadScene(Scene scene)
	{
		delegate.loadScene(scene);
	}

	@Override
	public void swapScene(Scene scene)
	{
		delegate.swapScene(scene);
	}

	@Override
	public boolean tileInFrustum(Scene scene, float pitchSin, float pitchCos, float yawSin, float yawCos,
		int cameraX, int cameraY, int cameraZ, int plane, int msx, int msy)
	{
		return delegate.tileInFrustum(scene, pitchSin, pitchCos, yawSin, yawCos, cameraX, cameraY, cameraZ, plane, msx, msy);
	}

	@Override
	public boolean zoneInFrustum(int zoneX, int zoneZ, int maxY, int minY)
	{
		return delegate.zoneInFrustum(zoneX, zoneZ, maxY, minY);
	}

	@Override
	public void loadScene(WorldView worldView, Scene scene)
	{
		delegate.loadScene(worldView, scene);
	}

	@Override
	public void despawnWorldView(WorldView worldView)
	{
		delegate.despawnWorldView(worldView);
	}

	@Override
	public void preSceneDraw(Scene scene, Projection entityProjection,
		float cameraX, float cameraY, float cameraZ, float cameraPitch, float cameraYaw,
		int minLevel, int level, int maxLevel, Set<Integer> hideRoofIds)
	{
		delegate.preSceneDraw(scene, entityProjection, cameraX, cameraY, cameraZ, cameraPitch, cameraYaw,
			minLevel, level, maxLevel, hideRoofIds);
	}

	@SuppressWarnings("deprecation")
	@Override
	public void preSceneDraw(Scene scene,
		float cameraX, float cameraY, float cameraZ, float cameraPitch, float cameraYaw,
		int minLevel, int level, int maxLevel, Set<Integer> hideRoofIds)
	{
		delegate.preSceneDraw(scene, cameraX, cameraY, cameraZ, cameraPitch, cameraYaw,
			minLevel, level, maxLevel, hideRoofIds);
	}

	@Override
	public void postSceneDraw(Scene scene)
	{
		delegate.postSceneDraw(scene);
	}

	@Override
	public void drawPass(Projection entityProjection, Scene scene, int pass)
	{
		delegate.drawPass(entityProjection, scene, pass);
	}

	@Override
	public void drawZoneOpaque(Projection entityProjection, Scene scene, int zx, int zz)
	{
		delegate.drawZoneOpaque(entityProjection, scene, zx, zz);
	}

	@Override
	public void drawZoneAlpha(Projection entityProjection, Scene scene, int level, int zx, int zz)
	{
		delegate.drawZoneAlpha(entityProjection, scene, level, zx, zz);
	}

	@Override
	public void invalidateZone(Scene scene, int zx, int zz)
	{
		delegate.invalidateZone(scene, zx, zz);
	}
}

package com.github.jasparigus.lefthanded;

import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.api.events.ClientTick;
import net.runelite.api.hooks.DrawCallbacks;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

import javax.inject.Inject;
import java.util.Arrays;
import java.util.Objects;

/**
 * Mirrors the local player's mesh (sword side, asymmetrical gear) for a left-handed appearance.
 *
 * <p>Takes over the client's draw callbacks slot by wrapping the active renderer (the GPU plugin),
 * and flips the live model's vertex x-values and face winding inside {@code drawTemp} - the call
 * site where the game client hands the actor's model to the renderer, which reads it synchronously
 * during upload; the flip is restored immediately afterwards (verified: edits made at
 * BeforeRender or the renderable draw callback never reach the upload).
 */
@Slf4j
@PluginDescriptor(
	name = "Left Handed",
	internalName = "left-handed",
	description = "Mirror your character mesh for a left-handed appearance",
	tags = {"left", "handed", "mirror", "bow"}
)
public class LeftHandedPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private LeftHandedConfig config;

	@Inject
	private ClientThread clientThread;

	/** null while the slot holds the vanilla renderer (or is empty: CPU mode). */
	private LeftHandedDrawCallbacks wrapper;

	private boolean bowEquipped;
	private String lastMatchedWeapon;
	private boolean equipmentDumped;
	private String declinedRenderer;

	@Override
	protected void startUp() throws Exception
	{
		log.debug("Left Handed started!");
	}

	@Override
	protected void shutDown() throws Exception
	{
		detach();
		bowEquipped = false;
		lastMatchedWeapon = null;
		equipmentDumped = false;
		declinedRenderer = null;
		log.debug("Left Handed stopped!");
	}

	@Subscribe
	public void onClientTick(ClientTick clientTick)
	{
		// attach() is polled rather than event-driven: it idempotently self-heals every slot
		// transition (GPU plugin toggles reclaiming/emptying the slot, other model-swap plugins
		// stacking on top) within one tick.
		if (config.mode() != LeftHandedConfig.LeftHandMode.OFF)
		{
			attach();
			if (config.mode() == LeftHandedConfig.LeftHandMode.BOW_ONLY)
			{
				bowEquipped = detectBow();
			}
		}
	}

	/**
	 * Wraps the renderer currently in the draw callbacks slot. Must run on the client thread.
	 * CPU mode (null slot) is unsupported: the CPU renderer draws without DrawCallbacks, so
	 * there is no vertex-accurate hook point; the wrapper is left detached there.
	 */
	private void attach()
	{
		final DrawCallbacks current = client.getDrawCallbacks();
		if (current == null)
		{
			if (wrapper != null)
			{
				wrapper = null; // GPU went away
			}
			logOnce(null);
			return;
		}
		if (current == wrapper)
		{
			return; // already attached
		}
		if (wrapper != null)
		{
			// We were silently stacked under or evicted by another renderer (GPU restart reclaims
			// the slot). Adopt whatever sits on top now.
			log.debug("Left Handed: draw callbacks slot changed to {}, re-wrapping", current.getClass().getName());
		}
		wrapper = new LeftHandedDrawCallbacks(current, this::mirrorActive,
			gameObject -> gameObject.getRenderable() == client.getLocalPlayer());
		client.setDrawCallbacks(wrapper);
		declinedRenderer = null;
		log.debug("Left Handed: mirroring wrapper installed over {}", current.getClass().getName());
	}

	private void detach()
	{
		final LeftHandedDrawCallbacks w = wrapper;
		wrapper = null;
		if (w == null)
		{
			return;
		}
		// Hard kill first: takes effect on the render thread immediately, so mirroring stops even
		// if the slot restore below is deferred or never lands.
		w.setEnabled(false);
		// shutDown() may run on the AWT thread (plugin panel toggle) while setDrawCallbacks
		// asserts the client thread - throwing from shutDown() aborts the whole plugin stop,
		// leaving this plugin subscribed, its config live, and the wrapper mirroring forever.
		final DrawCallbacks delegate = w.getDelegate();
		clientThread.invoke(() ->
		{
			if (client.getDrawCallbacks() == w)
			{
				client.setDrawCallbacks(delegate);
			}
			else
			{
				// Slot was reclaimed by the renderer (e.g. it re-installs itself); restoring over
				// it would evict the renderer. The disabled wrapper just delegates from here on.
				log.debug("Left Handed: draw-callbacks slot no longer ours on detach; leaving disabled wrapper in place");
			}
		});
	}

	private boolean mirrorActive()
	{
		switch (config.mode())
		{
			case ALWAYS:
				return true;
			case BOW_ONLY:
				return bowEquipped;
			default:
				return false;
		}
	}

	private boolean detectBow()
	{
		final Player player = client.getLocalPlayer();
		if (player == null)
		{
			return false;
		}
		final PlayerComposition composition = player.getPlayerComposition();
		if (composition == null)
		{
			return false;
		}
		// Scan every equipment slot and match by item name. getEquipmentId(KitType.WEAPON) is
		// unusable on this client: its logs showed the weapon slot reporting helmet and ammo IDs,
		// and this fork's kit enum diverges from the raw array layout past index 5.
		final int[] equipment = composition.getEquipmentIds();
		if (equipment == null)
		{
			return false;
		}
		if (!equipmentDumped)
		{
			equipmentDumped = true;
			log.debug("Left Handed: raw equipment {}", Arrays.toString(equipment));
		}
		String matched = null;
		for (final int raw : equipment)
		{
			final int itemId;
			if (raw >= PlayerComposition.ITEM_OFFSET)
			{
				itemId = raw - PlayerComposition.ITEM_OFFSET;
			}
			else if (raw > 0 && raw < PlayerComposition.KIT_OFFSET)
			{
				itemId = raw; // raw-id convention (kits live in [KIT_OFFSET, ITEM_OFFSET))
			}
			else
			{
				continue; // kit or empty
			}
			final ItemComposition item = client.getItemDefinition(itemId);
			final String name = item == null ? "" : item.getMembersName().toLowerCase();
			if (!name.contains("bow"))
			{
				continue;
			}
			// OSRS crossbows are one-handed, so mirroring them is a taste call - config decides.
			if (name.contains("crossbow") && !config.mirrorCrossbows())
			{
				continue;
			}
			matched = item.getMembersName();
			break;
		}
		if (!Objects.equals(matched, lastMatchedWeapon))
		{
			lastMatchedWeapon = matched;
			log.debug("Left Handed: bow equipment {}", matched == null ? "<none>" : matched);
		}
		return matched != null;
	}

	private void logOnce(String renderer)
	{
		final String key = renderer == null ? "<none>" : renderer;
		if (declinedRenderer != null && declinedRenderer.equals(key))
		{
			return;
		}
		declinedRenderer = key;
		log.debug("Left Handed: no wrapping possible (draw callbacks slot: {})", key);
	}

	@Provides
	LeftHandedConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(LeftHandedConfig.class);
	}
}

package com.github.jasparigus.lefthanded;

import net.runelite.api.Model;

/**
 * Mirrors a model mesh about its vertical (X) axis. Two operations, both self-inverse, so calling
 * {@link #mirrorModelX(Model)} twice restores the model exactly - which lets the draw-callbacks
 * wrapper flip the local player's model only for the duration of the renderer's synchronous
 * upload and restore it immediately afterwards.
 *
 * <p>The face-winding swap is mandatory, not cosmetic: the GPU renderer's sorted upload culls
 * faces by screen-space winding (cross-product area sign), so negating X alone inverts every
 * triangle and the renderer draws the inside of the mesh instead of the outside.
 *
 * <p>Vertex normals are deliberately untouched: the GPU upload paths do not read them (lighting
 * comes from pre-baked face colors), and normal arrays are shared references across actors with
 * the same appearance, so editing them would corrupt other models.
 */
final class MeshMirror
{
	private MeshMirror()
	{
	}

	/**
	 * Negates all vertex x-coordinates, swaps the second/third face indices of every face, and
	 * swaps the matching per-corner face colors so shading travels with the swapped vertices.
	 */
	static void mirrorModelX(Model model)
	{
		mirrorVerticesX(model.getVerticesX(), model.getVerticesCount());
		final int faceCount = model.getFaceCount();
		swapFaceWinding(model.getFaceIndices2(), model.getFaceIndices3(), faceCount);
		final int[] colors2 = model.getFaceColors2();
		final int[] colors3 = model.getFaceColors3();
		if (colors2 != null && colors3 != null)
		{
			swapFaceColors(colors2, colors3, faceCount);
		}
	}

	/**
	 * Swaps per-corner face colors for faces that have ordinary shading. Faces whose third color
	 * is not a real color are skipped: the renderer's convention is {@code faceColors3 == -1}
	 * (flat face: all corners use color1) and {@code faceColors3 == -2} (hidden face: skipped at
	 * upload. Swapping those markers between the two arrays would un-hide hidden faces and upload
	 * raw negative values as corner colors. Skipping is self-inverse: faceColors2 always holds a
	 * real color (>= 0), so after a swap the third slot still tests >= 0 for the restore pass, and
	 * never-swapped special faces keep failing the test forever.
	 */
	static void swapFaceColors(int[] colors2, int[] colors3, int faceCount)
	{
		final int count = Math.min(faceCount, Math.min(colors2.length, colors3.length));
		for (int i = 0; i < count; i++)
		{
			if (colors3[i] >= 0)
			{
				final int tmp = colors2[i];
				colors2[i] = colors3[i];
				colors3[i] = tmp;
			}
		}
	}

	/**
	 * Negates the first {@code vertCount} x-coordinates in place.
	 */
	static void mirrorVerticesX(float[] vx, int vertCount)
	{
		for (int i = 0; i < vertCount; i++)
		{
			vx[i] = -vx[i];
		}
	}

	/**
	 * Swaps the two arrays' entries pairwise for the first {@code count} entries (clamped to the
	 * shorter array), flipping triangle winding (indices) or the matching corner colors.
	 */
	static void swapFaceWinding(int[] indices2, int[] indices3, int faceCount)
	{
		final int count = Math.min(faceCount, Math.min(indices2.length, indices3.length));
		for (int i = 0; i < count; i++)
		{
			final int tmp = indices2[i];
			indices2[i] = indices3[i];
			indices3[i] = tmp;
		}
	}
}

package com.github.jasparigus.lefthanded;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class LeftHandedPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(LeftHandedPlugin.class);
		RuneLite.main(args);
	}
}

package com.github.jasparigus.lefthanded;

import org.junit.Test;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;

public class MeshMirrorTest
{
	@Test
	public void mirrorNegatesX()
	{
		float[] vx = {3f, -4f, 0f, 7f};
		MeshMirror.mirrorVerticesX(vx, vx.length);
		float[] expected = {-3f, 4f, -0f, -7f};
		for (int i = 0; i < vx.length; i++)
		{
			// bit-exact: the sign of zero must be preserved (mirror of 0.0f is -0.0f)
			assertEquals(Float.floatToRawIntBits(expected[i]), Float.floatToRawIntBits(vx[i]));
		}
	}

	@Test
	public void doubleMirrorRestoresOriginal()
	{
		float[] original = {3f, -4f, 0f, 7f, Float.MAX_VALUE, Float.MIN_VALUE};
		float[] vx = original.clone();
		MeshMirror.mirrorVerticesX(vx, vx.length);
		MeshMirror.mirrorVerticesX(vx, vx.length);
		assertArrayEquals(original, vx, 0f);
	}

	@Test
	public void mirrorPartiallyNegatesOnlyVertexCount()
	{
		float[] vx = {1f, 2f, 3f, 4f};
		MeshMirror.mirrorVerticesX(vx, 2);
		assertArrayEquals(new float[]{-1f, -2f, 3f, 4f}, vx, 0f);
	}

	@Test
	public void windingSwapsAndRestores()
	{
		int[] i2 = {10, 20, 30};
		int[] i3 = {11, 21, 31};
		MeshMirror.swapFaceWinding(i2, i3, 3);
		assertArrayEquals(new int[]{11, 21, 31}, i2);
		assertArrayEquals(new int[]{10, 20, 30}, i3);
		MeshMirror.swapFaceWinding(i2, i3, 3);
		assertArrayEquals(new int[]{10, 20, 30}, i2);
		assertArrayEquals(new int[]{11, 21, 31}, i3);
	}

	@Test
	public void windingSwapsOnlyFaceCountNotArrayLength()
	{
		// model arrays are often longer than faceCount; only the drawn faces must be touched
		int[] i2 = {1, 2, 999};
		int[] i3 = {4, 5, 888};
		MeshMirror.swapFaceWinding(i2, i3, 2);
		assertArrayEquals(new int[]{4, 5, 999}, i2);
		assertArrayEquals(new int[]{1, 2, 888}, i3);
	}

	@Test
	public void cornerColorSwapSkipsSpecialValuesAndRestores()
	{
		// faceColors3 special values (-1 flat, -2 hidden) must never be moved into faceColors2,
		// and the >= 0 condition stays self-inverse because faceColors2 always holds real colors
		int[] c2 = {0x111111, 0x222222, 0x333333};
		int[] c3 = {0xAAAAAA, -1, -2};
		MeshMirror.swapFaceColors(c2, c3, 3);
		assertArrayEquals(new int[]{0xAAAAAA, 0x222222, 0x333333}, c2);
		assertArrayEquals(new int[]{0x111111, -1, -2}, c3);
		MeshMirror.swapFaceColors(c2, c3, 3);
		assertArrayEquals(new int[]{0x111111, 0x222222, 0x333333}, c2);
		assertArrayEquals(new int[]{0xAAAAAA, -1, -2}, c3);
	}
}
